38865700' WHEN dateTime>1440759900 AND dateTime<1440763800 THEN '2015:1440759900:1440763800' WHEN dateTime>1443606000 AND dateTime<1443609600 THEN '2015:1443606000:1443609600' WHEN dateTime>1447841400 AND dateTime<1447845900 THEN '2015:1447841400:1447845900' WHEN dateTime>1450864200 AND dateTime<1450867800 THEN '2015:1450864200:1450867800' WHEN dateTime>1451047800 AND dateTime<1451085000 THEN '2015:1451047800:1451085000' END AS gap_id, outTemp,outHumidity,rain,rainRate,windSpeed,windGust,windDir,barometer,usUnits,`interval` FROM `pocasi-loucka.eu`.archive WHERE (dateTime>1422621600 AND dateTime<1422627000) OR (dateTime>1423554600 AND dateTime<1423559700) OR (dateTime>1428317700 AND dateTime<1428325200) OR (dateTime>1428325800 AND dateTime<1428332100) OR (dateTime>1428339600 AND dateTime<1428344700) OR (dateTime>1428345000 AND dateTime<1428348600) OR (dateTime>1428349800 AND dateTime<1428356100) OR (dateTime>1428364200 AND dateTime<1428369900) OR (dateTime>1428373800 AND dateTime<1428384900) OR (dateTime>1428389400 AND dateTime<1428414000) OR (dateTime>1428586500 AND dateTime<1428592500) OR (dateTime>1428594000 AND dateTime<1428602700) OR (dateTime>1429112400 AND dateTime<1429125000) OR (dateTime>1429187400 AND dateTime<1429199700) OR (dateTime>1432824300 AND dateTime<1432830600) OR (dateTime>1433324100 AND dateTime<1433336400) OR (dateTime>1436270400 AND dateTime<1436295000) OR (dateTime>1437067500 AND dateTime<1437079800) OR (dateTime>1437126600 AND dateTime<1437139200) OR (dateTime>1438527900 AND dateTime<1438536300) OR (dateTime>1438707900 AND dateTime<1438711800) OR (dateTime>1438749600 AND dateTime<1438753800) OR (dateTime>1438759500 AND dateTime<1438763400) OR (dateTime>1438803900 AND dateTime<1438865700) OR (dateTime>1440759900 AND dateTime<1440763800) OR (dateTime>1443606000 AND dateTime<1443609600) OR (dateTime>1447841400 AND dateTime<1447845900) OR (dateTime>1450864200 AND dateTime<1450867800) OR (dateTime>1451047800 AND dateTime<1451085000)) AS hits
